

import { forwardRef } from "react";

export type InstalacaoPortfolio = {
  foto: string;
  cidade: string;
  descricao: string;
};

export type DadosPreview = {
  nome: string;
  telefone: string;
  cidade: string;
  consumo: string;
  valorConta: string;
  geracao: string;
  potencia: string;
  quantidadeModulos: string;
  marcaModulo: string;
  modeloModulo: string;
  potenciaModulo: string;
  moduloBifacial: boolean;
  quantidadeInversores: string;
  marcaInversor: string;
  modeloInversor: string;
  potenciaInversor: string;
  tipoInversor: "String" | "Microinversor";
  valorProposta: string;
  parcelasCartao: number;
  totalCartao: string;
  parcelaCartao: string;
  parcelasFinanciamento: number;
  totalFinanciamento: string;
  parcelaFinanciamento: string;
  instalacoes: InstalacaoPortfolio[];
  enderecoLoja: string;
  garantiaDesempenhoModulo: string;
  garantiaModulo: string;
  garantiaInversor: string;
  garantiaInstalacao: string;
  temaPDF: "claro" | "escuro";
};

type PreviewPropostaProps = { dados: DadosPreview };

const LOGO = "/imagens/logo/brasao-choqueseg.png";
const TELHADO = "/imagens/capa/telhado.solar.png";
const FOTO_EQUIPE = "/imagens/capa/capa.gerador.png";

const IMAGENS_EQUIPAMENTOS: Partial<Record<TipoIcone, string>> = {
  modulo: 'data:image/png;base64,',
  inversor: 'data:image/png;base64,',
  estrutura: 'data:image/png;base64,',
  cabos: 'data:image/png;base64,',
  protecao: 'data:image/png;base64,',
};

const meses = ["Jan", "Fev", "Mar", "Abr", "Mai", "Jun", "Jul", "Ago", "Set", "Out", "Nov", "Dez"];
const fatoresAracaju = [1.08, 1.06, 1.02, 0.96, 0.88, 0.84, 0.86, 0.91, 0.98, 1.06, 1.17, 1.18];

function numero(valor?: string | number | null) {
  const texto = String(valor ?? "");
  const limpo = texto.replace(/[^\d,.-]/g, "").replace(/\./g, "").replace(",", ".");
  const convertido = Number(limpo);
  return Number.isFinite(convertido) ? convertido : 0;
}

function dinheiro(valor: number) {
  return valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

function hoje() {
  return new Intl.DateTimeFormat("pt-BR").format(new Date());
}

function textoSeguro(...partes: Array<string | undefined | null>) {
  return partes.filter((parte) => Boolean(parte && parte.trim())).join(" ").replace(/\s+/g, " ").trim();
}

const PreviewProposta = forwardRef<HTMLDivElement, PreviewPropostaProps>(
  function PreviewProposta({ dados }, ref) {
    const consumo = Math.max(numero(dados.consumo), 0);
    const geracaoMedia = Math.max(numero(dados.geracao), 0);
    const contaAtual = Math.max(numero(dados.valorConta), 0);
    const investimento = Math.max(numero(dados.valorProposta), 0);
    const quantidadeModulos = Math.max(Math.round(numero(dados.quantidadeModulos)), 0);
    const quantidadeInversores = Math.max(Math.round(numero(dados.quantidadeInversores)), 1);
    // Cálculo comercial da economia:
    // 1. tarifa média estimada = valor da conta / consumo informado;
    // 2. energia compensada = menor valor entre geração e consumo;
    // 3. economia energética = energia compensada x tarifa média;
    // 4. por segurança, a economia exibida nunca ultrapassa 90% da conta,
    //    preservando custos residuais como disponibilidade/taxas.
    const tarifaMediaEstimada =
      consumo > 0 && contaAtual > 0 ? contaAtual / consumo : 0;

    const energiaCompensada =
      consumo > 0 && geracaoMedia > 0
        ? Math.min(consumo, geracaoMedia)
        : 0;

    const economiaEnergetica =
      tarifaMediaEstimada > 0 && energiaCompensada > 0
        ? energiaCompensada * tarifaMediaEstimada
        : 0;

    const limiteEconomia =
      contaAtual > 0 ? contaAtual * 0.9 : 0;

    const economiaMensal =
      Math.min(economiaEnergetica, limiteEconomia);

    const economiaAnual = economiaMensal * 12;

    const payback =
      economiaAnual > 0 && investimento > 0
        ? investimento / economiaAnual
        : 0;

    const percentualEconomiaExibido =
      contaAtual > 0 && economiaMensal > 0
        ? Math.round((economiaMensal / contaAtual) * 100)
        : 0;

    const coberturaEnergeticaExibida =
      consumo > 0 && geracaoMedia > 0
        ? Math.min(Math.round((geracaoMedia / consumo) * 100), 100)
        : 0;

    const dadosGrafico = meses.map((mes, indice) => ({
      mes,
      consumo,
      geracao: geracaoMedia * fatoresAracaju[indice],
    }));
    const maiorValor = Math.max(...dadosGrafico.flatMap((item) => [item.consumo, item.geracao]), 1);

    const descricaoModulo = textoSeguro(
      quantidadeModulos ? `${quantidadeModulos} módulos` : "",
      dados.moduloBifacial ? "bifaciais" : "",
      dados.marcaModulo,
      dados.modeloModulo,
      dados.potenciaModulo,
    ) || "Módulos solares selecionados na proposta";

    const descricaoInversor = textoSeguro(
      `${quantidadeInversores.toString().padStart(2, "0")} ${dados.tipoInversor === "Microinversor" ? (quantidadeInversores === 1 ? "microinversor" : "microinversores") : (quantidadeInversores === 1 ? "inversor" : "inversores")}`,
      dados.marcaInversor,
      dados.modeloInversor,
      dados.potenciaInversor,
    );

    const escuro = dados.temaPDF === "escuro";
    const fundoPagina = escuro ? "bg-zinc-950 text-white" : "bg-white text-zinc-950";
    const fundoSecaoClara = escuro ? "bg-zinc-900 text-white" : "bg-white text-zinc-950";
    const tituloPagina = escuro ? "text-white" : "text-zinc-950";

    return (
      <div ref={ref} className="flex flex-col items-center gap-6 bg-zinc-900 p-3">
        {/* ===================== PÁGINA 1 ===================== */}
        <Pagina numero="1/3" tema={dados.temaPDF}>
          <Hero />

          <div
            className={`mt-3 grid shrink-0 grid-cols-3 gap-3 rounded-2xl p-3 ${
              escuro ? "bg-zinc-900 text-white" : "bg-zinc-100 text-zinc-950"
            }`}
          >
            <InfoTopo icone="pessoa" titulo="Cliente" valor={dados.nome || "Nome do cliente"} />
            <InfoTopo icone="local" titulo="Cidade" valor={dados.cidade || "Cidade / SE"} />
            <InfoTopo icone="data" titulo="Data" valor={hoje()} />
          </div>

          <div className="mt-3 grid min-h-0 flex-1 grid-cols-[1.08fr_0.92fr] gap-3">
            <section
              className={`flex min-h-0 flex-col rounded-2xl border-2 border-yellow-400 p-4 ${fundoSecaoClara}`}
            >
              <h2 className="text-[30px] font-black uppercase leading-[1.02] text-current">
                O que está incluso<br />na sua instalação
              </h2>

              <div className="mt-4 grid flex-1 content-between gap-2">
                <ItemEquipamento escuro={escuro} tipo="modulo" titulo="Módulos solares" texto={descricaoModulo} />
                <ItemEquipamento escuro={escuro} tipo="inversor" titulo={dados.tipoInversor === "Microinversor" ? "Microinversor" : "Inversor"}
                  texto={descricaoInversor || "Equipamento de conversão selecionado"}
                />
                <ItemEquipamento escuro={escuro} tipo="estrutura" titulo="Estrutura de fixação" texto="Estrutura metálica em alumínio de alta resistência" />
                <ItemEquipamento escuro={escuro} tipo="cabos" titulo="Cabos e conectores" texto="Cabos solares CC, conectores MC4 e materiais de interligação" />
                <ItemEquipamento escuro={escuro} tipo="protecao" titulo="Proteção elétrica" texto="Disjuntores, DPS e dispositivos de proteção nos lados CA e CC" />
                <ItemEquipamento escuro={escuro} tipo="ferramenta" titulo="Instalação completa" texto="Equipe especializada CHOQUESEG" />
                <ItemEquipamento escuro={escuro} tipo="documento" titulo="Projeto e documentação" texto="Projeto elétrico e documentação técnica" />
                <ItemEquipamento escuro={escuro} tipo="energisa" titulo="Homologação na Energisa" texto="Aprovação do projeto junto à concessionária" />
                <ItemEquipamento escuro={escuro} tipo="monitoramento" titulo="Monitoramento" texto="Configuração do aplicativo e orientação de uso" />
              </div>
            </section>

            <section className="flex min-h-0 flex-col rounded-2xl border-2 border-yellow-400 bg-zinc-950 p-4 text-white">
              <h2 className="text-[31px] font-black uppercase leading-[0.98] text-yellow-400">
                Etapas do<br />seu projeto
              </h2>

              <div className="mt-4 grid flex-1 content-between gap-3">
                <Etapa numero="1" icone="analise" titulo="Análise técnica" texto="Levantamento das informações e visita técnica quando necessário." />
                <Etapa numero="2" icone="documento" titulo="Projeto elétrico" texto="Elaboração do projeto e documentação necessária." />
                <Etapa numero="3" icone="energisa" titulo="Homologação" texto="Aprovação do projeto junto à Energisa." />
                <Etapa numero="4" icone="engrenagem" titulo="Instalação" texto="Instalação dos equipamentos, conexões e testes." />
                <Etapa numero="5" icone="monitoramento" titulo="Monitoramento" texto="Configuração do sistema e entrega técnica." />
                <Etapa numero="6" icone="suporte" titulo="Suporte pós-venda" texto="Orientação de uso e suporte da nossa equipe." />
              </div>

              <div className="mt-4 shrink-0 rounded-2xl bg-yellow-400 p-4 text-zinc-950">
                <div className="flex items-center gap-3">
                  <Icone tipo="aperto" tamanho={58} />
                  <p className="text-[19px] font-black uppercase leading-tight">
                    Da aprovação até a sua economia, você conta com a CHOQUESEG!
                  </p>
                </div>
              </div>
            </section>
          </div>

          <Rodape endereco={dados.enderecoLoja} />
        </Pagina>

        {/* ===================== PÁGINA 2 ===================== */}
        <Pagina numero="2/3" tema={dados.temaPDF}>
          <Hero />

          <section className="mt-3 shrink-0">
            <h2 className={`text-[31px] font-black uppercase leading-none ${tituloPagina}`}>
              Resumo do seu sistema
            </h2>
            <div className="mt-3 grid grid-cols-4 gap-3">
              <CardResumo icone="raio" titulo="Potência" valor={dados.potencia || "—"} />
              <CardResumo icone="grafico" titulo="Geração/mês" valor={dados.geracao ? `${dados.geracao} kWh` : "—"} />
              <CardResumo icone="modulo" titulo="Módulos" valor={quantidadeModulos ? `${quantidadeModulos} × ${dados.potenciaModulo}` : "—"} />
              <CardResumo
                icone="inversor"
                titulo={dados.tipoInversor === "Microinversor" ? "Microinversor" : "Inversor"}
                valor={dados.potenciaInversor || "—"}
              />
            </div>
          </section>

          <section className="mt-3 shrink-0">
            <h2 className={`text-[31px] font-black uppercase leading-none ${tituloPagina}`}>
              Investimento
            </h2>

            <div className="mt-3 grid grid-cols-[1.55fr_0.85fr] gap-3">
              <div className="rounded-2xl bg-yellow-400 p-5 text-zinc-950">
                <p className="text-[21px] font-black uppercase">Valor à vista</p>
                <strong className="mt-2 block text-[44px] font-black leading-none">
                  {dados.valorProposta || "—"}
                </strong>
              </div>

              <div className="flex flex-col items-center justify-center rounded-2xl border border-yellow-400 bg-zinc-950 p-4 text-center text-white">
                <p className="text-[19px] font-black uppercase">Economia de até</p>
                <strong className="text-[48px] font-black leading-none text-yellow-400">90%</strong>
                <span className="text-[13px] font-black uppercase">na conta de energia</span>
              </div>
            </div>

            <div className="mt-3 grid grid-cols-2 gap-3">
              <CardPagamento
                titulo="Parcelamento no cartão"
                icone="cartao"
                destaque={`Até ${dados.parcelasCartao}x`}
                detalhe={dados.parcelaCartao !== "—" ? `${dados.parcelasCartao}x de ${dados.parcelaCartao}` : "Consulte as condições"}
              />
              <CardPagamento
                titulo="Financiamento"
                icone="banco"
                destaque={`Até ${dados.parcelasFinanciamento}x`}
                detalhe={dados.parcelaFinanciamento !== "—" ? `${dados.parcelasFinanciamento}x de ${dados.parcelaFinanciamento} · sujeito à aprovação` : "1ª parcela em até 120 dias · sujeito à aprovação"}
              />
              <CardPagamento
                titulo="Retorno do investimento"
                icone="relogio"
                destaque={payback > 0 ? `${payback.toFixed(1)} anos` : "Estimativa"}
                detalhe="Payback estimado conforme consumo e investimento"
              />
              <CardPagamento
                titulo="Economia estimada"
                icone="folha"
                destaque={economiaMensal > 0 ? `${dinheiro(economiaMensal)}/mês` : "Informe a conta"}
                detalhe={
                  economiaAnual > 0
                    ? `${dinheiro(economiaAnual)} por ano · ${percentualEconomiaExibido}% da conta`
                    : "Calculada pela relação entre consumo, geração e conta atual"
                }
              />
            </div>
          </section>

          <section className="mt-3 flex min-h-0 flex-1 flex-col rounded-2xl border-2 border-yellow-400 bg-zinc-950 p-4 text-white">
            <div className="flex items-end justify-between gap-4">
              <div>
                <p className="text-[16px] font-black uppercase text-yellow-400">Geração x consumo</p>
                <h3 className="text-[29px] font-black uppercase leading-tight">Perfil anual estimado</h3>
              </div>
              <div className="flex gap-5 text-[13px] font-bold">
                <Legenda cor="amarelo" texto="Geração (kWh)" />
                <Legenda cor="branco" texto="Consumo (kWh)" />
              </div>
            </div>

            <div className="mt-4 grid min-h-0 flex-1 grid-cols-12 items-end gap-2.5">
              {dadosGrafico.map((item) => (
                <div key={item.mes} className="flex h-full flex-col items-center justify-end">
                  <div className="mb-1 text-[12px] font-black text-white">
                    {Math.round(item.geracao)}
                  </div>
                  <div className="flex h-[220px] w-full items-end justify-center gap-1">
                    <Barra valor={item.geracao} max={maiorValor} classe="bg-yellow-400" />
                    <Barra valor={item.consumo} max={maiorValor} classe="bg-white" />
                  </div>
                  <span className="mt-2 text-[12px] font-black uppercase">{item.mes}</span>
                </div>
              ))}
            </div>
          </section>

          <Rodape endereco={dados.enderecoLoja} />
        </Pagina>

        {/* ===================== PÁGINA 3 ===================== */}
        <Pagina numero="3/3" tema={dados.temaPDF}>
          <Hero />

          <section
            className={`mt-3 shrink-0 rounded-2xl border-2 border-yellow-400 p-4 ${fundoSecaoClara}`}
          >
            <div className="flex items-baseline justify-between gap-3">
              <h2 className="text-[29px] font-black uppercase leading-none">Garantias</h2>
              <p className={escuro ? "text-[12px] font-bold text-zinc-300" : "text-[12px] font-bold text-zinc-500"}>
                Conforme os equipamentos informados na proposta
              </p>
            </div>

            <div className="mt-3 grid grid-cols-4 gap-3">
              <Garantia titulo="Desempenho do módulo" anos={dados.garantiaDesempenhoModulo} icone="modulo" />
              <Garantia titulo="Garantia do inversor" anos={dados.garantiaInversor} icone="inversor" />
              <Garantia titulo="Garantia do módulo" anos={dados.garantiaModulo} icone="modulo" />
              <Garantia titulo="Garantia da instalação" anos={dados.garantiaInstalacao} icone="ferramenta" />
            </div>
          </section>

          <section className="mt-3 flex min-h-0 flex-1 flex-col rounded-2xl border-2 border-yellow-400 bg-zinc-950 p-4 text-white">
            <div className="shrink-0">
              <h2 className="text-[30px] font-black uppercase leading-none">Nossa experiência</h2>
              <p className="mt-2 text-[15px] font-bold">
                Algumas instalações realizadas pela CHOQUESEG
              </p>
            </div>

            <div className="mt-4 grid min-h-0 flex-1 grid-cols-2 grid-rows-2 gap-3">
              {dados.instalacoes.slice(0, 4).map((instalacao, indice) => (
                <figure
                  key={`${indice}-${instalacao.foto}`}
                  className="flex min-h-0 flex-col overflow-hidden rounded-2xl border-2 border-yellow-400 bg-zinc-900"
                >
                  <div className="min-h-0 flex-1 bg-zinc-800">
                    {instalacao.foto ? (
                      <img src={instalacao.foto} alt="" className="h-full w-full object-cover" />
                    ) : (
                      <div className="flex h-full items-center justify-center px-4 text-center text-[15px] font-black uppercase text-current opacity-60">
                        Adicione uma foto da instalação
                      </div>
                    )}
                  </div>

                  <figcaption className="shrink-0 border-t border-yellow-400 bg-black px-4 py-3">
                    <p className="text-[15px] font-black leading-tight text-white">
                      📍 {instalacao.cidade || "Local da instalação"}
                    </p>
                    <p className="mt-1 text-[13px] font-bold leading-tight text-yellow-400">
                      {instalacao.descricao || "Sistema fotovoltaico CHOQUESEG"}
                    </p>
                  </figcaption>
                </figure>
              ))}
            </div>
          </section>

          <section className="mt-3 shrink-0 rounded-2xl bg-yellow-400 px-5 py-4 text-zinc-950">
            <div className="flex items-center justify-between gap-5">
              <div className="flex items-center gap-4">
                <Icone tipo="sol" tamanho={52} />
                <p className="text-[24px] font-black uppercase leading-tight">
                  Vamos deixar o sol pagar pelo seu conforto?
                </p>
              </div>
              <div className="rounded-xl bg-black px-5 py-3 text-[17px] font-black uppercase text-white">
                Quero fechar com a CHOQUESEG! ›
              </div>
            </div>
          </section>

          <Rodape endereco={dados.enderecoLoja} />
        </Pagina>
      </div>
    );
  },
);

export default PreviewProposta;

function Pagina({
  children,
  numero,
  tema,
}: {
  children: React.ReactNode;
  numero: string;
  tema: "claro" | "escuro";
}) {
  return (
    <article
      data-pagina-proposta
      className={`relative flex h-[1123px] w-[794px] flex-col overflow-hidden p-[10px] font-sans shadow-2xl ${
        tema === "escuro" ? "bg-zinc-950 text-white" : "bg-white text-zinc-950"
      }`}
      style={{ boxSizing: "border-box" }}
    >
      <div className="pointer-events-none absolute inset-0 rounded-[24px] border-2 border-yellow-400" />
      {children}
      <div className="absolute right-[16px] top-[10px] z-30 rounded-bl-xl bg-yellow-400 px-4 py-1.5 text-[12px] font-black uppercase text-black">
        Página {numero}
      </div>
    </article>
  );
}

